import { getCategories, getPosts, getUsers } from "@/lib/api";
import TopNav from "@/components/TopNav";
import HeroCarousel from "@/components/HeroCarousel";
import CategoryTabs from "@/components/CatagoryTaps";
import RankedPostList from "@/components/RankedPostList";
import SidebarLoginCard from "@/components/SidebarLoginCard";
import CreatorRecommend from "@/components/CreatorRecommend";
import RecentFeed from "@/components/RecentFeed";

interface HomePageProps {
  searchParams: { category?: string; q?: string };
}

export default async function HomePage({ searchParams }: HomePageProps) {
  const [categories, users] = await Promise.all([getCategories(), getUsers()]);

  const activeCategory = categories.find(
    (category) => category.slug === searchParams.category
  );

  const posts = await getPosts({
    categoryId: activeCategory?.id,
    query: searchParams.q,
  });

  const userMap = new Map(users.map((user) => [user.id, user.nickname]));
  const authorNickname = (authorId: number) => userMap.get(authorId) ?? "";

  const heroPosts = [...posts]
    .sort((a, b) => b.sympathyCount - a.sympathyCount)
    .slice(0, 4);
  const rankedPosts = [...posts]
    .sort((a, b) => b.sympathyCount - a.sympathyCount)
    .slice(0, 5);
  const recentPosts = [...posts]
    .sort(
      (a, b) => new Date(b.createdAt).getTime() - new Date(a.createdAt).getTime()
    )
    .slice(0, 4);

  return (
    <div className="page">
      <TopNav />
      <div className="content-layout">
        <main className="content-main">
          <HeroCarousel posts={heroPosts} authorNickname={authorNickname} />
          <CategoryTabs categories={categories} activeSlug={searchParams.category} />
          {posts.length === 0 ? (
            <p className="empty-state">조건에 맞는 글이 없습니다.</p>
          ) : (
            <RankedPostList posts={rankedPosts} blogName={authorNickname} />
          )}
        </main>
        <aside className="content-sidebar">
          <SidebarLoginCard />
          <CreatorRecommend creators={users} />
          <RecentFeed posts={recentPosts} />
        </aside>
      </div>
    </div>
  );
}